/**
  * @bref	write flash
  * @param	flash_s
  * @retval	flash_s
  */
flash_s flash_write_imp(flash_s in)
{
	flash_s out = in;
	__disable_irq(); // отключаем прерывания, чтобы не нарушать процесс записи
	out.status = HAL_FLASH_Unlock();
	if (out.status != HAL_OK)
	{
		goto end;
	}

	uint32_t FlashMemAddress = FLASH_SECTOR5_BASE_ADDRESS;

	for (size_t i = 0; i < in.count; ++i)
	{
		out.status = HAL_FLASH_Program(FLASH_TYPEPROGRAM_BYTE, FlashMemAddress, in.data[i]);
		if (out.status != HAL_OK)
		{
			HAL_FLASH_Lock();
			goto end;
		}
		FlashMemAddress += 1;
	}

	out.status = HAL_FLASH_Lock();
end:
	__enable_irq();
	return out;
}

/**
  * @bref	erase flash
  * @param	flash_s
  * @retval	flash_s
  */
flash_s flash_erase_imp(flash_s in)
{
	flash_s out = in;
	__disable_irq(); // отключаем прерывания, чтобы не нарушать процесс записи
	out.status = HAL_FLASH_Unlock();
	if (out.status != HAL_OK)
	{
		goto end;
	}

	FLASH_EraseInitTypeDef FlashErase = {
			.Sector = FLASH_SECTOR_5,
			.NbSectors = 1,
			.TypeErase = FLASH_TYPEERASE_SECTORS,
			.VoltageRange = (int8_t)VOLTAGE_RANGE_3,
	};
	uint32_t SectorError = 0;

	out.status = HAL_FLASHEx_Erase(&FlashErase, &SectorError);
	if (out.status != HAL_OK)
	{
		HAL_FLASH_Lock();
		goto end;
	}

	out.status = HAL_FLASH_Lock();
end:
	__enable_irq();
	return out;
}

