void Read_Page(uint32_t addr, uint8_t *rData)
{
	uint8_t temp[4] = {0,};
	while (Read_SR1() & 1)
	{
		__NOP();
	}
	W25_CSL;
	temp[0] = READ;
	temp[1] = (addr>>16) & 0xff;
	temp[2] = (addr>>8) & 0xff;
	temp[3] = addr & 0xff;
	HAL_SPI_Transmit(&hspi1, temp, 4, 1);
	while (HAL_SPI_GetState(&hspi1) != HAL_SPI_STATE_READY)
	{
		__NOP();
	}
	HAL_SPI_Receive(&hspi1, rData, 256, 1);
	W25_CSH;
}

void WriteEnable(void)
{
	uint8_t temp[1];
	W25_CSL;
	temp[0] = WRITE_EN;
	HAL_SPI_Transmit(&hspi1, temp, 1, 1);
	W25_CSH;
}

void WriteDisable(void)
{
	uint8_t temp[1];
	W25_CSL;
	temp[0] = WRITE_DS;
	HAL_SPI_Transmit(&hspi1, temp, 1, 1);
	W25_CSH;
}

void Write_Page(uint32_t addr, uint8_t *wData)
{
	uint8_t temp[4] = {0,};
	while (Read_SR1() & 1)
	{
		__NOP();
	}
	W25_CSL;
	temp[0] = WRITE;
	temp[1] = (addr>>16) &  0xff;
	temp[2] = (addr>>8) & 0xff;
	temp[3] = addr & 0xff;
	HAL_SPI_Transmit(&hspi1, temp, 4, 1);
	HAL_SPI_Transmit(&hspi1, wData, 256, 1);
	while (HAL_SPI_GetState(&hspi1) != HAL_SPI_STATE_READY)
	{
		__NOP();
	}
	W25_CSH;
}

void EraseSec(uint32_t addr)
{
	uint8_t temp[4] = {0,};
	while (Read_SR1() & 1)
	{
		__NOP();
	}
	W25_CSL;
	temp[0] = ERASE_SEC;
	temp[1] = (addr>>16) & 0xff;
	temp[2] = (addr>>8) & 0xff;
	temp[3] = addr & 0xff;
	HAL_SPI_Transmit(&hspi1, temp, 4, 1);
	W25_CSH;
	HAL_Delay(1);
}

// using
void loop()
{
	if (!HAL_GPIO_ReadPin(GPIOE, GPIO_PIN_3))
	{
		HAL_GPIO_WritePin(GPIOA, GPIO_PIN_7, GPIO_PIN_RESET);
		Read_Page(0, buffer);
		sprintf(str_tx,
				"ID: %x\r\n" \
				"JEDEC: %lx\r\n" \
				"%02x %02x %02x %02x %02x %02x %02x %02x %02x\r\n",
				Read_ID(), Read_JEDEC(),
				buffer[0], buffer[1], buffer[2], buffer[3], buffer[4], buffer[5], buffer[6], buffer[7], buffer[8]);
		CDC_Transmit_FS((unsigned char*)str_tx, strlen(str_tx));
		HAL_Delay(500);
		HAL_GPIO_WritePin(GPIOA, GPIO_PIN_7, GPIO_PIN_SET);
		goto end;
	}
	else if (!HAL_GPIO_ReadPin(GPIOE, GPIO_PIN_4))
	{
		HAL_GPIO_WritePin(GPIOA, GPIO_PIN_7, GPIO_PIN_RESET);
		if (flash_is_empty)
		{
			WriteEnable();
			for (uint16_t i = 0; i < 256; ++i)
			{
				buffer[i] = 0xff;
			}
			buffer[0] = 0x55;
			buffer[1] = 0xff;
			buffer[2] = 0x00;
			buffer[3] = 0xAA;
			Write_Page(0, buffer);
			WriteDisable();
			flash_is_empty = false;
			sprintf(str_tx, "Flash has modified!\r\n");
			CDC_Transmit_FS((unsigned char*)str_tx, strlen(str_tx));
			HAL_Delay(500);
			HAL_GPIO_WritePin(GPIOA, GPIO_PIN_7, GPIO_PIN_SET);
			goto end;
		}
		else if (buffer[0] != 0xff)
		{
			WriteEnable();
			EraseSec(0);
			WriteDisable();
			flash_is_empty = true;
			sprintf(str_tx, "Flash has erased!\r\n");
			CDC_Transmit_FS((unsigned char*)str_tx, strlen(str_tx));
			HAL_Delay(500);
			HAL_GPIO_WritePin(GPIOA, GPIO_PIN_7, GPIO_PIN_SET);
		}
		goto end;
	}
	HAL_Delay(500);

	end:
		__NOP();
	return;
}

